#!/bin/bash
#
# Builds the iOS engine library and its Swift binding for the iOS engine bundle
# (.github/release/engine-bundle-layout.md).
#
#  1. `yadorilink-mobile-ffi` as a static library (release) for the device
#     (aarch64-apple-ios) and the simulator (aarch64-apple-ios-sim).
#  2. The Swift source and C header UniFFI generates from the device library, plus the
#     module map the header needs. The simulator library has the same API checksums.
#
# Everything is written to one output directory (default: ios-binding/ under cargo's
# target directory):
#
#   device/libyadorilink_mobile_ffi.a       bundle root `device`
#   simulator/libyadorilink_mobile_ffi.a    bundle root `simulator`
#   Generated/                              bundle root `generated`
#
# The app lives in its own repository and builds against the bundle; nothing here is
# checked in. The generated code refuses to load a library whose API checksums differ,
# so the bundle ships the libraries and the Swift generated from them together.
#
# The release build exports YADORILINK_RELEASE_ID and YADORILINK_CHANNEL before calling this
# script, so both libraries name their own build.
#
# Usage:
#   .github/release/generate-ios-binding.sh [--out DIR]

set -euo pipefail

OUT_DIR=""
if [ "${1:-}" = "--out" ]; then
    OUT_DIR="${2:?--out needs a directory}"
elif [ -n "${1:-}" ]; then
    echo "usage: $0 [--out DIR]" >&2
    exit 2
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
# The minimum iOS the engine is built for (replicated File Provider is iOS 16+); the same
# default as .github/ci/ios-check.sh.
export IPHONEOS_DEPLOYMENT_TARGET="${IPHONEOS_DEPLOYMENT_TARGET:-16.0}"
DEVICE=aarch64-apple-ios
SIMULATOR=aarch64-apple-ios-sim
LIB=libyadorilink_mobile_ffi.a

export PATH="$HOME/.cargo/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"
cd "$REPO_ROOT"

TARGET_DIR="$(cargo metadata --format-version 1 --no-deps \
    | python3 -c 'import json, sys; print(json.load(sys.stdin)["target_directory"])')"

for target in "$DEVICE" "$SIMULATOR"; do
    echo "== building yadorilink-mobile-ffi ($target, release) =="
    cargo build --locked -p yadorilink-mobile-ffi --release --target "$target"
done
echo "== building the Swift binding generator =="
cargo build --locked -p yadorilink-mobile-ffi --features bindgen --bin uniffi-bindgen-swift-mobile

OUT_DIR="${OUT_DIR:-$TARGET_DIR/ios-binding}"
BINDGEN="$TARGET_DIR/debug/uniffi-bindgen-swift-mobile"
for target in "$DEVICE" "$SIMULATOR"; do
    test -f "$TARGET_DIR/$target/release/$LIB" || { echo "missing $TARGET_DIR/$target/release/$LIB"; exit 1; }
done

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

"$BINDGEN" --swift-sources --headers "$TARGET_DIR/$DEVICE/release/$LIB" "$WORK/raw"

mkdir -p "$WORK/Generated/include"
cp "$WORK/raw/"*.swift "$WORK/Generated/"
cp "$WORK/raw/"*.h "$WORK/Generated/include/"
# One clang module per generated header, named the way the generated Swift imports it.
{
    echo "// Generated by .github/release/generate-ios-binding.sh. Do not edit."
    for header in "$WORK/Generated/include/"*.h; do
        name="$(basename "$header" .h)"
        printf 'module %s {\n    header "%s.h"\n    export *\n}\n' "$name" "$name"
    done
} > "$WORK/Generated/include/module.modulemap"

rm -rf "$OUT_DIR/Generated" "$OUT_DIR/device" "$OUT_DIR/simulator"
mkdir -p "$OUT_DIR/device" "$OUT_DIR/simulator"
cp -R "$WORK/Generated" "$OUT_DIR/Generated"
cp "$TARGET_DIR/$DEVICE/release/$LIB" "$OUT_DIR/device/$LIB"
cp "$TARGET_DIR/$SIMULATOR/release/$LIB" "$OUT_DIR/simulator/$LIB"

echo "== iOS binding written: $OUT_DIR =="
